{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a polyglycosylated natural product, was the least concentrated in rat brain and could hardly pass the BBB, indicating that hydrophilic sugar-conjugated molecules such as the glucuronide-bearing query have poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Posiphen, a lipophilic N-methylated fused-ring carbamate, achieved a brain-to-plasma ratio of 5.04 in mice and was labeled high permeability, showing that some related scaffolds can penetrate well when they lack the polar glucuronide.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Cymserine entered rat brain with a brain-to-plasma ratio of 40:1, demonstrating high CNS penetration for lipophilic phenserine-type carbamates, but these structures do not contain the query's ionizable glucuronic acid moiety.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a glucuronide-conjugated morphinan (morphine-3-glucuronide-like) with a polar, ionizable sugar acid and multiple hydroxyls. Although several lipophilic alkaloid/carbamate analogues show high brain penetration, the only glycoside-like negative control (epimedin B) and the known physicochemical barrier of glucuronidation indicate inadequate CNS access. The positive CNS penetrants lack the glucuronide and are therefore less transferable. Prediction: fail.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query molecule itself; transfer relies on glycoside analog and known glucuronide pharmacology.",
    "No transporter/efflux data for the query, which could further limit CNS access.",
    "No human data for the query's CNS exposure after systemic administration."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

